/* Сгенерировано из site/data/proverbs.json — правьте его, не этот файл. */
const PROVERBS = [{"english":"Oh father, save me from the small one, the big one I shall manage myself.","russian":"Отец, избавь меня от маленького, а с большим я и сам справлюсь.","somali":"Aabbe, kan yar iga celiyoo kan weyn igu sii daa"},{"english":"Oh Allah, do not punish a man who sins through ignorance [i.e. who unknowingly violates religious precepts].","russian":"О Аллах, не карай того, кто грешит по невежеству [т. е.  кто неосознанно нарушает религиозные заповеди].","somali":"Allow, nimaan wax ogayn ha cadaabin"},{"english":"To know something for sure, one would even part with a she-camel.","russian":"Чтобы знать что-либо наверняка, не жаль отдать и верблюдицу.","somali":"Hubsiimo hal baa la siistaa"},{"english":"Do not speak for [lit: do not serve for] a mouth that is present [i.e. one should not speak on behalf of a person who is present].","russian":"За присутствующий рот не говорят [букв.: ему не прислуживают].","somali":"Af jooga looma adeego"},{"english":"The soul tells you to run as fast as you can [i.e. to save your life with all your might].","russian":"Душа велит тебе бежать со всех ног [т. е. изо всех сил спасать свою жизнь].","somali":"Naftu orod bay kugu aammintaa"},{"english":"A hunchback knows how he should sleep [i.e. every man knows better than you what he needs].","russian":"Горбатый лучше (тебя) знает, как ему спать [т. е. каждый сам лучше других знает свои нужды].","somali":"Nin tuur lihi siduu u seexdo isagaa yaqaan"},{"english":"Each bird flies only with birds [lit.: bird] of its own kind.","russian":"Каждая птица летает с себе подобной.","somali":"Shimbirba shimbirkiisuu la duulaa"},{"english":"Oh mouth, you have eaten something, now keep quiet [i.e. do not object to he who has fed you].","russian":"Рот, ты поел, так теперь помалкивай [т. е. не возражай давшему поесть].","somali":"Af wax cunay, xishow"},{"english":"A lie leaves no trace [i.e. nothing remains of it].","russian":"Ложь не оставляет следов [т. е. от неё ничего не остаётся].","somali":"Beeni raad ma leh"},{"english":"One can tear something only with two hands.","russian":"Что-либо разорвать можно только двумя руками.","somali":"Gacmo wadajir bay wax ku gooyaan"},{"english":"To an old woman who is sitting down, wrestling seems to be the simplest thing [i.e. when one takes a detached view, every job seems easy].","russian":"Сидящей старухе кажется, что бороться легко [т. е. со стороны всякое дело кажется лёгким].","somali":"Habar fadhidaa legdan la fududaa"},{"english":"Either refuse (to do something) at once or put up with it later.","russian":"Либо откажись сразу, либо потом терпи","somali":"Ama afeef hore lahow, ama adkeysi dambe lahow"},{"english":"Do not reject me until you know me well [i.e. one should not be judged by appearances].","russian":"Не отвергай меня, не узнав хорошенько.","somali":"Barasho horteed hay nicin"},{"english":"Beggars and ailing people are disliked equally.","russian":"Попрошаек и больных одинаково не любят.","somali":"Baryo badan iyo bukaan badanba waa laysku nacaa"},{"english":"You will be drowned by two things: plenty of water and plenty of enemies.","russian":"Много воды —  утонешь, много врагов —  утопят.","somali":"Col kaa badan iyo biyo kaa badanba way ku hafiyaan"},{"english":"Where the jackal has got accustomed to fat brisket, he will eventually die of starvation.","russian":"Там, где шакал привык к жирной грудинке, он когда-нибудь подохнет от истощения","somali":"Dawaco meeshay macal uga baratay ayay macaluul ugu baqtidaa"},{"english":"He who brought the jinnee [i.e. the trouble] must take it away.","russian":"Кто джинна [т. е. беду] привёл, тот его и увести должен.","somali":"Jinni ninkii keenaa bixiya"},{"english":"One does not throw away fruit in the pocket for the sake of fruit on the tree.","russian":"Ради плодов, растущих на дереве, не высыпают тех, что в кармане.","somali":"Miro gunti ku jira kuwo geed saaran looma daadiyo"},{"english":"One brings a woman into a house by deception, but lives with her by truth [i.e. promises a lot, but has to live with reality].","russian":"Женщину в дом вводят обманом, да живут с ней правдой [т. е. много обещают, а живут по возможности].","somali":"Naag been waa lagu soo xero geliyaa, runna waa lagu dhaqaa"},{"english":"An old man knows where his death may come from [i.e. what may threaten him].","russian":"Старый человек знает, откуда ему смерти ждать [т. е. откуда грозит опасность].","somali":"Nin weyni wedkii waa yaqaan"},{"english":"The absence of knowledge is the absence of light.","russian":"Без знаний — всё равно, что без света.","somali":"Aqoonla'aani waa iftiinla'aan"},{"english":"One should neither be late for the wedding nor stay too long at it.","russian":"На свадьбу не опаздывают и на ней не засиживаются.","somali":"Aroos lagama raago, lagumana raago"},{"english":"Unless one of the debaters gives in, it will not rain [i.e. no headway will be made in the matter].","russian":"Пока один из спорщиков не уступит, дождь не пойдёт [т. е. дело не сдвинется с места].","somali":"Haddaan la kala roonaan, roob ma da'o"},{"english":"One has to change many mats for the man who is incontinent.","russian":"Под страдающим недержанием мочи приходится часто менять циновку. \tУпотребляется в значении: с несдержанным человеком, приходится быть особенно терпеливым.","somali":"Kaadi-badane waa loo gogol badiyaa"},{"english":"If you fail to know someone in an hour, you will not know them in a year.","russian":"Кого не узнаешь за час, не узнаешь и за год.","somali":"Nin aanad saacad ku baran sanad kuma baratid"},{"english":"Those who accept a favour are many [lit: have been seen], but those who pay back are none [lit: have not been seen].","russian":"Тех, кто принимает услугу, много [букв.: их видели], а тех, кто платит за неё, — совсем нет [букв.: их не видели].","somali":"Abaal nin gala waa la arkay, nin gudase lama arag"},{"english":"Your previous lie damages your present truth.","russian":"Твоя прежняя ложь вредит твоей нынешней правде.","somali":"Beentaada hore runtaada danbay u baas baxdaa"},{"english":"As the pancakes are piled, so [i.e. in such sequence] they should be eaten.","russian":"Как лепёшки сложены, так [т. е. в такой последовательности] их и есть следует.","somali":"Canjeelo siday u kala korreyso ayaa loo cunaa"},{"english":"A just sentence cannot make happy [lit: make laugh] both sides at once.","russian":"Справедливое решение суда не может обрадовать [букв.: рассмешить] обе стороны сразу.","somali":"Gari laba nin kama wada qosliso"},{"english":"If you are dying, wipe off your saliva [i.e. try to die suitably].","russian":"Кода умираешь — утирай слюну [т. е. старайся умереть достойно].","somali":"Haddaad dhimaneysid dhareerka waa layska duwaa"},{"english":"He to whom you gave birth did not give birth to you [i.e. your child does not treat you in the same way as you treat him].","russian":"Тот, кого родил ты, тебя не рожал [т. е. твой ребёнок относится к тебе не так, как ты к нему].","somali":"Nin aad dhashay kuma dhalin"},{"english":"The sandals of a dead man are more valuable than he is [there is no benefit from a dead man].","russian":"Сандалии мертвеца лучше его самого [так как от мертвеца нет никакой пользы].","somali":"Nin dhintay kabihiisaa dhaama"},{"english":"He who praises himself is like a she-goat which suckles herself.","russian":"Тот, кто сам себя хвалит, похож на козу, которая сама себя сосёт.","somali":"Nin is faanshay waa ri' is nuugtay"},{"english":"Do not eat carrion even if you are (very) hungry [i.e. do not bring shame upon yourself under any circumstances].","russian":"Не ешь падаль, даже если (очень) голоден [т. е. не срамись ни при каких обстоятельствах].","somali":"‘Waan baahan ahay’ bakhtiga looma cuno"},{"english":"A grown man should not be told to go away, but should be shown the best way to do it [in order to leave with dignity].","russian":"Взрослому человеку не говорят „уходи!“, а показывают, как удобнее всего уйти [чтобы он мог уйти с достоинством].","somali":"Waayeel ‘tag’ lama yidhaahdo ee wuxuu ku tagaa la tusaa"},{"english":"If you want to get more, you will lose everything.","russian":"Погонишься за большим — потеряешь всё","somali":"Wax badso wax beel bay leedahay"},{"english":"My father has killed a mouse, will he fail to kill a man [lit: people]?","russian":"Мой отец убил мышь, —  так неужели он человека [букв.: людей] убить не сможет?","somali":"Abkay doolli dilow, dad nool maas u daahaa?"},{"english":"A bald spot reveals itself unexpectedly.","russian":"Лысина появляется, когда её не ждёшь.","somali":"Bidaari sibiq bay kugu gashaa"},{"english":"Oh fool, your fire is too hot!","russian":"О, дурак, твой огонь слишком жжёт!","somali":"Doqoneey, dabkaa ba'!"},{"english":"A fool has no luck.","russian":"Дураку не везёт.","somali":"Doqoni calaf ma leh"},{"english":"You may kill an infidel [if he deserves it] but be just to him [i.e. be just even to your enemy].","russian":"Неверного можешь убить [если он того заслуживает], но будь к нему справедлив [т. е. относись справедливо даже к своему врагу].","somali":"Gaal dil, gartiisana sii"},{"english":"Many words cannot fill a pitcher.","russian":"Многословием кувшина не наполнишь.","somali":"Hadal haan ma buuxsho"},{"english":"One naked man cannot carry another naked man [i.e. one poor man cannot help another poor man].","russian":"Голый голого не унесёт [т. е.  бедный бедному помочь не может].","somali":"Laba qaawani isma qaaddo"},{"english":"In the rainless season dry grass is (rich) fodder.","russian":"Когда нет дождя, даже сухая трава —  корм.","somali":"Lamahuraan waa cawska jiilaal"},{"english":"He who warned you, saved you [lit: did not kill you].","russian":"Кто тебя предупредил, тот тебя спас [букв.: тот тебя не убил].","somali":"Nin kuu digay kuma dilin"},{"english":"The sleeping herdsman's cow calves a he-calf.","russian":"Спящему (пастуху) корова телёнка [а не тёлку] приносит.","somali":"Ninkii seexdaa sicii dibi dhal"},{"english":"Every prayer should be offered at its proper time.","russian":"Каждой молитве — своё время.","somali":"Salaad walba waqtigeedaa la tukadaa"},{"english":"There is a stone in every date [i.e. something bad in every good thing].","russian":"В каждом финике есть косточка [т. е.  в каждой хорошей вещи есть плохая часть].","somali":"Timir laf baa ku jirta"},{"english":"The character (of a man) was formed before the arguments [and therefore no form of persuasion can change it].","russian":"Характер (человека) сложился до уговоров [и никакими уговорами его нельзя изменить].","somali":"Waano abuuris baa ka horreysay"},{"english":"The restless foot is bound to step in something.","russian":"Беспокойная нога во что-нибудь да вляпается.","somali":"Cagtii joogsan weyda mar bay ceeb la kulantaa"},{"english":"A fire lit by a sinful man burns a sinless man.","russian":"В огне, который зажигает грешник, сгорает праведник.","somali":"Dab munaafaq shiday mu’min baa ku gubta"},{"english":"In striving for gains you will sit even on a dog skin.","russian":"Ради собственной выгоды и на собачью шкуру сядешь.","somali":"Dantaada maqaar ey baa loogu seexdaa"},{"english":"He drove the cattle from plague to glanders [i.e. he escaped one disaster, but got into another].","russian":"Увёл (скот) от язвы, а пригнал к сапу [т. е. избежал одной беды, но попал в другую].","somali":"Kud ka guur oo qanjo u guur"},{"english":"A snake must be killed by a blow to its head [i.e. in order to defeat the enemy, you need to strike at the most vulnerable place].","russian":"Змею убивают ударом по голове [т. е. чтобы одолеть врага, нужно нанести удар в его самое уязвимое место].","somali":"Mas madaxaa laga dilaa"},{"english":"For he who does not work (even) tea is impure [i.e. he does not even have the right to a cup of tea].","russian":"Кто не работает, для того и чай —  скоромное [т. е. он не имеет права даже на чашку чая].","somali":"Nin aan shaqaysan shaahi waa ka xaaraan"},{"english":"A man caught by a flood clings to the foam.","russian":"Попавший в поток хватается за пену.","somali":"Nin daad qaaday xunbo cuskay"},{"english":"The man who guards the sleep of others should not sleep.","russian":"Кто стережёт сон других, тот сам спать не должен.","somali":"Nin lagu seexdow, ha seexan"},{"english":"He who does not hear the word ‘stop!’ will hear the words ‘lie down!’ [i.e. he who does not listen to warnings will get into trouble].","russian":"Тот, кто не слышит слова „стой!“, услышит слово „ложись!“ [т. е.  тот, кто не внимает предупреждению об опасности, попадёт в беду].","somali":"Ninkii ‘soo joog’ laga waayo ‘soo jiifso’ ayaa laga helaa"},{"english":"It makes no difference if you carry or drag branches [to make a fence] —  they will get to the same yard [lit.: house].","russian":"Что нести ветки, что волочить [для сооружения изгороди] —  всё в один и тот же двор [букв.: дом].","somali":"Oodi qaadis iyo jiidis waa isla guri geyn"},{"english":"There is not yet a fire for the first dates!","russian":"Ещё и для первых фиников огня нет!","somali":"Timirtii horaba dab loo waa"},{"english":"In what one hides (from people) there is always something bad [lit: a piece of shit].","russian":"В том, что скрывают (от людей), всегда есть что-то плохое [букв.: кусок дерьма].","somali":"Wax la qariyo qurun baa ku jira"},{"english":"‘I have a donkey’ is better than ‘My father used to have cattle’.","russian":"Лучше „У меня есть осёл“, чем „У моего отца было много скота“.","somali":"‘Aabbahay baa xoolo lahaan jiray’ ‘anigaa dameer leh’ ayaa ka roon"},{"english":"A camel (in a caravan) follows the tracks of the leading camel.","russian":"Верблюд (в караване) идёт след в след с предыдущим.","somali":"Awrba awrka ka horreeya ayuu saanqaadkiisa leeyahay"},{"english":"Protect yourself from the water before it overflows [i.e. trouble should be prevented in advance].","russian":"Отгородись от воды, пока она не разлилась [т. е. беду следует предотвращать заранее].","somali":"Biyo intaysan ku soo gaarin ayaa layska moosaa"},{"english":"For a muddle-headed pupil everything should be written in capital letters [i.e. everything has to be explained particularly clearly to someone who is slow to understand].","russian":"Бестолковому ученику всё пишут крупными буквами [т. е. тому, кто плохо понимает, приходится всё разъяснять особенно подробно].","somali":"Damiin faro waaweyn baa wax loogu qoraa"},{"english":"One finger cannot wash a face.","russian":"Одним пальцем не умоешься.","somali":"Far keliya fool ma dhaqdo"},{"english":"One surpasses the person from whom one has learned.","russian":"У кого научился, того превзошёл.","somali":"Laga barayba laga badi"},{"english":"A cat in its own house has lion's fangs.","russian":"В своём доме у кошки клыки львиные.","somali":"Mukulaal mininkeeda joogtaa miciyo libaax bay leedahay"},{"english":"A woman may be managed only by a man who is old enough to be her father [i.e. a husband should be considerably older than his wife].","russian":"С женщиной управится лишь тот, кто ей годится в отцы [т. е. муж должен быть значительно старше жены].","somali":"Naag nin dhali karaa dhaqa"},{"english":"A woman does not think of a man whom she knows well, as a man.","russian":"Женщина не считает мужчиной того, кого хорошо знает.","somali":"Naagi nin ay taqaan nin ma mooddo"},{"english":"Either suffer without women or suffer with them.","russian":"Либо терпи без женщин, либо терпи от них.","somali":"Naago ama u samir, ama ka samir"},{"english":"A woman is never too small.","russian":"Женщина слишком маленькой не бывает.","somali":"Naago yaraan ma leh"},{"english":"It is written on the face [lit: neck] of everyone that he thinks himself good.","russian":"По лицу [букв.: по шее] каждого человека видно, что он считает себя хорошим.","somali":"Nin walba kitaab qummane ah ayaa qoorta ugu jira"},{"english":"Somalis can lie, but their lie will never become a proverb.","russian":"Сомалиец может соврать, но враньё никогда не станет пословицей.","somali":"Soomaalidu been waa sheegtaa, beense ma maahmaahdo"},{"english":"It is not bad to ask each other for something, but it is bad to dodge each other.","russian":"Не дурно друг у друга просить — дурно друг с другом лукавить.","somali":"Wax is weyddiini ma xuma ee wax is weydaarsi baa xun"},{"english":"Either be visible or be absent [i.e. either do a job well or do not set about it at all].","russian":"Либо будь на виду, либо не показывайся [т. е.  либо делай дело хорошо, либо не берись за него вовсе].","somali":"Ama waa la muuqdaa, ama waa la maqnaadaa"},{"english":"If trouble turns its back on you, don’t make it turn to face you.","russian":"Если беда от тебя отвернулась, не заставляй её повернуться к тебе.","somali":"Belaayo kaa sii jeedda layskuma soo jeediyo"},{"english":"One drinks enough water only from one’s own hands [lit.: palms].","russian":"Вдоволь напьёшься только из своих рук [букв.: ладоней].","somali":"Biyo sacabbadaada ayaa looga dhergaa"},{"english":"An old man should not disgrace himself [lit.: one should not see off one’s old age in disgrace].","russian":"Старому человеку позориться не пристало [букв.: свою старость провожать позором не следует].","somali":"Cimri tegay ceeb laguma sagootiyo"},{"english":"If you live long you will see how the camels are born.","russian":"Поживёшь подольше — увидишь, как верблюды рожают.","somali":"Cimrigaagoo dheeraadaa geel dhalayuu ku tusaa"},{"english":"Where there is gain, there is no shame.","russian":"Где есть нажива, там нет стыда.","somali":"Dani xishood ma leh"},{"english":"All camels were once two years old [i.e. everyone was young once].","russian":"Все верблюды когда-то были двухлетками [т. е. когда-то все были молодыми].","somali":"Geel laba jir soo wada mar"},{"english":"You tell him one thing, but he hears another.","russian":"Ты говоришь одно, а он слышит другое","somali":"Hadal nin si u yiri, ninna si u qaaday"},{"english":"Teeth bite only when they bite together.","russian":"Зубы кусают только вместе.","somali":"Ilko wadajir bay wax ku gooyaan"},{"english":"One should not talk where one should give something [i.e. one should help].","russian":"Там, где надо дать [т. е. помочь], разговаривать не следует.","somali":"Meel ‘hoo’ u baahan hadal wax kama taro"},{"english":"One does not ask ‘Who are you?’ of a man one knows [i.e. it is senseless to ask about something you know].","russian":"У знакомого не спрашивают: „Кто ты такой?“ [т. е. о том, что уже знаешь, спрашивать не имеет смысла].","somali":"Nin aad taqaan ‘yaad tahay?’ lama yiraahdo"},{"english":"A husband and wife are neither at war nor at peace.","russian":"Муж с женой и не воюют, и не мирятся.","somali":"Nin iyo naagtii colna ma aha, nabadna ma aha"},{"english":"There is nothing to cook yet, but he is already gathering brushwood!","russian":"Ещё варить нечего, а он уже хворост собирает!","somali":"Quud aan jirin qoryo u guro"},{"english":"Only once did a bird carry fire, and even then it burned its mother’s nest.","russian":"Только раз птица огонь взяла, да и то сожгла гнездо своей матери.","somali":"Shimbiri mar bay dab qaadday, markiina buulkii hooyadeed bay gubtay"},{"english":"Either propose something yourself or agree to what is proposed by others.","russian":"Либо предлагай сам, либо соглашайся с тем, что предлагают другие.","somali":"Ama talo keen ahow, ama talo raac ahow"},{"english":"Lost cattle end up with someone who has no need of them [i.e. sometimes something needed by one person ends up with someone who has no need of it].","russian":"Пропавшая скотина оказывается у того, кому она не нужна [т. е. порой нужная вещь оказывается не у того, кто в ней нуждается, а у того, кому она ни к чему].","somali":"Baadiyi nin aan lahayn bay ag joogtaa"},{"english":"I eat not carrion, but soup made from carrion.","russian":"Я ем не падаль, а суп из падали.","somali":"Baqtiga ma cunee fuudkiisaan cabbaa"},{"english":"Water flows to a low place.","russian":"Вода собирается там, где низко.","somali":"Biyo meel godan bay isugu tagaan"},{"english":"The finger knows where you ache [i.e. it always touches the sore spot].","russian":"Палец знает, где у тебя болит [т. е. он всегда касается больного места].","somali":"Farta iyo meesha buktaa is og"},{"english":"The man who does something is the one to scold.","russian":"Кто дело делает, того и бранят.","somali":"Nin xil qaaday eed qaad"},{"english":"Only he who can manage his own affairs can manage those of others [i.e. can help others].","russian":"Лишь тот, кто справляется со своими делами, может справиться и с чужими [т. е. может помочь другим].","somali":"Ninkii tiisa daryeelaa tu kale ku dara"},{"english":"Before you have time to tell a thief that he is a thief, he calls you a thief.","russian":"Прежде чем ты назовёшь вора вором, он успеет назвать вором тебя.","somali":"Tuug intaadan ‘tuug’ dhihin buu ‘tuug’ ku dhahaa"},{"english":"You will not remain (on earth) – let a good memory of you remain.","russian":"Ты сам не останешься (на земле) — пусть останется о тебе добрая память.","somali":"Waari mayside war ha kaa haro"},{"english":"The camels went for water and a donkey skipped with them.","russian":"Верблюды отправились по воду —  и осёл с ними.","somali":"Dameeri dhaan raacday"},{"english":"A swine is cursed only because it is a swine.","russian":"Свинью ругают лишь за то, что она свинья.","somali":"Doofaar ficilla'aan baa loo cadaabaa"},{"english":"God does not spare (people), but cares for them [i.e. while causing people to suffer for their sins, he at the same time gives them everything they need].","russian":"Бог не щадит (людей), но заботится о них [т. е. посылая людям страдания за их грехи, он в то же время даёт им всё необходимое].","somali":"Eebbe ma naxee waa naxariistaa"},{"english":"A word is yours while it is in your chest [lit.: stomach].","russian":"Пока слово у тебя в груди [букв.: в животе] —  оно твоё.","somali":"Hadal intuu uurkaaga ku jiro ayuu ammaan yahay"},{"english":"A word is like sinew: it stretches in every direction [that is, what has been said can be interpreted in different ways].","russian":"Слово — что сухожилие: в какую сторону потянешь, в ту и растянется [т. е. сказанное может быть истолковано по-разному].","somali":"Hadal waa mergi hadba meel u jiidma"},{"english":"If somebody cheated you once he is a fool [because by the fraud he shook your faith in him], but if he cheated you twice you are a fool [because you believed him].","russian":"Если кто-то обманул тебя раз —  он глуп [потому что обманом подорвал доверие к себе], а если он обманул тебя дважды, то глуп ты [потому что поверил ему].","somali":"Mar i dage Alle ha dago, mar labaad i dagase anaa is dagay"},{"english":"Woman was created from a crooked rib.","russian":"Женщина создана из кривого ребра","somali":"Naag feedh qalloocan baa laga abuuray"},{"english":"A glutton is like a dead man [lit.: like one struck down by a sword].","russian":"Обжора — что мертвец [букв.: что сражённый мечом].","somali":"Nin soori kaa qaadday waa nin seefi kaa qaadday"},{"english":"A thief does not steal from another thief.","russian":"Вор у вора не крадёт","somali":"Tuug tuug ma xado"},{"english":"A closed mouth is gold.","russian":"Закрытый рот — золото","somali":"Af daboolan waa dahab"},{"english":"The locust flew away but it left hardship.","russian":"Саранча улетела, да беду оставила.","somali":"Ayax teg, eelna reeb"},{"english":"Enmity is never small [because each enmity can bring disaster].","russian":"Вражда малой не бывает [так как любая вражда грозит бедой].","somali":"Colaadi yaryaraysi ma leh"},{"english":"A pot boils from the heat [i.e. if someone is angry, there is a reason for it].","russian":"Горшок кипит от жара [т. е. если человек сердится, значит, на то есть причина].","somali":"Dheriga karka kulaylkaa ka keenay"},{"english":"The arrow will not fall out of your body however hard you may shake [i.e. no excuse will help you if you have been exposed].","russian":"Как ни трясись, стрела из тела не вывалится [т.е. если тебя уличили, оправдания не помогут].","somali":"Fallaadhi gilgilasho kaagama go'do"},{"english":"Think before you do something.","russian":"Прежде чем cделать, подумай.","somali":"Intaadan falin ka fiirso"},{"english":"A coward [lit: a man whose cowardice is betrayed by his eyes] is beaten with his own stick.","russian":"Труса [букв.: человека, трусость которого выдают его глаза] бьют его же собственной палкой.","somali":"Ishiisa-laga-arkaa ushiisa lagu tumaa"},{"english":"It is level at the rod standing upright and it is level at the rod lying flat.","russian":"И стоячему (жезлу) вровень, и лежачему (жезлу) вровень.","somali":"La jiifiyaana bannaan, la joojiyaana bannaan"},{"english":"An elephant does not see the gadfly which is sitting on it but sees the one sitting on another (elephant).","russian":"Слон не замечает овода, который сидит на нём, но видит того, что сидит на другом (слоне).","somali":"Maroodigu takarta saaran ma arkee kan kale tan saaran ayuu arkaa"},{"english":"If you come to the one-eyed people's country, pull out your eye.","russian":"Если попал в страну одноглазых, вырви себе глаз.","somali":"Meel il laga la'yahay haddaad tagto, il baa layska ridaa"},{"english":"He who is not going to unload (your camel) should not be the one to load (it).","russian":"Кто не собирается развьючивать (твоего верблюда), тот пусть (его) и не навьючивает.","somali":"Nin aan kuu furi doonin yuu kuu rarin"},{"english":"A sick person has a hundred advisers.","russian":"У больного сто советчиков","somali":"Nin bukaa boqol u talisay"},{"english":"The sling feels no animosity towards the birds [i.e. it kills them not through animosity, but by the will of the hunter].","russian":"Праща не питает вражды к птицам [т. е. она убивает их не из вражды, а по воле охотника].","somali":"Waraf iyo shimbiro war isuma hayaan"},{"english":"What does not eat you is eatable.","russian":"Что не ест тебя самого, то и съедобно.","somali":"Waxaan ku cuninba waa la cunaa"},{"english":"The cloth of the man who skirts about a clearing will not be torn by a tree [i.e. a cautious person will avoid troubles].","russian":"Кто обходит лес стороной, тот не порвёт одежду о дерево [т. е. осторожный человек избежит неприятностей].","somali":"Bannaankiisa-mare maradiisa geed ma qabsato"},{"english":"If a mule grazes with horses, it thinks that it is also a horse.","russian":"Если мул пасётся с лошадьми, то думает, что он тоже лошадь.","somali":"Baqal fardo la daaqday faras bay is mooddaa"},{"english":"He who has drunk your sour milk [i.e. whom you have reared] knows how to offend you (deeply).","russian":"Как тебя обидеть (побольнее), знает тот, кто пил твоё кислое молоко [т. е. тот, кого ты вскормил].","somali":"Ciirtaa-dhamaa ceebtaa yaqaan"},{"english":"An ugly she-ass kicks most angrily.","russian":"Уродливая ослица брыкается больше всех.","somali":"Dameeraha tan ugu foosha xun ayaa ugu haraanti kulul"},{"english":"Threaten a fool with a stick and if he misunderstands you beat him.","russian":"Погрози дураку палкой, а не поймёт — побей его.","somali":"Doqonta usha agteeda ku dhufo, hadday garan weydana gogga u geli"},{"english":"A stone flies [lit: falls] near, a word —  far off.","russian":"Камень летит [букв.: падает] близко, а слово — далеко.","somali":"Dhegi meel dheer bay ku dhacdaa, dhagaxna meel dhow"},{"english":"Do not trust [lit: do not talk to] he who gossips with you about others and with others about you.","russian":"Не верь тому [букв.: не разговаривай с тем], кто сплетничает с тобой о других, а с другими — о тебе.","somali":"Kuu-sheekeeye, kaa-sheekeeye ha la sheekeysan"},{"english":"If somebody of your age is being shaved, wet your own hair [i.e. get ready for the same trouble].","russian":"Если бреют твоего ровесника, намочи и ты свои волосы [т. e. приготовься сам к такой же беде].","somali":"Ninkii qayrkii loo xiirayow, soo qoyso adiguna"},{"english":"Allah himself helps a simple man to find a good place for his camp.","russian":"Бесхитростному человеку место для стоянки сам Аллах ищет.","somali":"Sir-ma-qabe Allaa u sahan ah"},{"english":"Your tongue steals what hides your soul [lit: stomach].","russian":"Что в душе [букв.: животе] кроется, то язык выдаёт [букв.: крадёт].","somali":"Wixii uurkaaga ku jira afkaa kaa xada"},{"english":"A problem can be seized (only) by its head, one cannot seize it by its tail [lit.: ankle].","russian":"Дело можно ухватить (только) за голову —  за хвост [букв.: за голень] его не ухватишь.","somali":"Arrini madax la qabtay leedahaye mijo la qabto ma leh"},{"english":"Tell lies, but let your lies resemble the truth.","russian":"Врать ври, но пусть твоё враньё походит на правду.","somali":"Been sheeg, laakiin been run u eg sheeg"},{"english":"A liar calls as witness one who is either dead or far away [i.e. someone who cannot come].","russian":"Лгун призывает в свидетели или мёртвого, или далёкого [т. е. того, кто не может прийти].","somali":"Beenlow nin dhintay iyo nin dheer ayuu marqaati u qabsadaa"},{"english":"A foal quietly suckles a she-donkey from behind [not being afraid of a kick].","russian":"Ослёнок сосёт ослицу сзади [не боясь, что она его лягнёт].","somali":"Dameeri isku-halleyn bay hooyadeed dabada uga nuugtaa"},{"english":"One can quickly put on town clothes, but it takes a long time to become a townsman.","russian":"Надеть городскую одежду можно быстро, но, чтобы стать горожанином, нужно время.","somali":"Dhar magaalo intii laga xirto waa dhow tahay, dhal magaalase intii lagu noqdo waa dheer tahay"},{"english":"Only a (timely) marriage or (untimely) death [lit: a grave] can keep your daughter (from disgrace).","russian":"От позора дочь убережёт лишь (своевременное) замужество или (безвременная) смерть [букв.: могила].","somali":"Gabar guri ha kaa gasho ama god"},{"english":"Justice knows only Allah.","russian":"Справедливость знает только Аллаха.","somali":"Gari Ilaah bay taqaan"},{"english":"‘I have a donkey’ is better than ‘I used to have camels’.","russian":"Лучше „У меня есть осёл“, чем „У меня были верблюды“.","somali":"‘Geel baan lahaan jiray’ ‘dameer baan leeyahay’ baa dhaanta"},{"english":"A thousand and one may court a girl [lit: a woman], but only one marries her.","russian":"За девушкой [букв.: женщиной] ухаживают тысяча и один, а женится один.","somali":"Naag kun baa koodisa iyo kow, kowgaana guursada"},{"english":"The law will not save you from the man you have failed to save yourself from with your fist.","russian":"От кого не избавит кулак [т. е.  сила], от того не избавит и закон.","somali":"Nin aan shantaadu kaa reebin sharci kaama reebo"},{"english":"If the blow missed you that does not mean that you may feel safe [because another blow can be delivered].","russian":"Если удар прошёл мимо тебя, это не значит, что ты можешь чувствовать себя в безопасности [так как в другой раз удар может достигнуть цели].","somali":"Nin sigtay ma noola"},{"english":"You cannot evade the camel which is driven [in your direction] by another camel, nor the man who is driven [i.e. set on you] by a woman [i.e. a woman skillfully uses a man for pursuing her ends].","russian":"Как от верблюда, которого гонит (в твою сторону) другой верблюд, так и от мужчины, которого гонит [т. е. натравливает на тебя] женщина, не увернёшься [т. е. женщина умело использует мужчину в своих целях].","somali":"Awr awr wado iyo nin naagi waddo, midna kaama baydho"},{"english":"If you dig a hole for somebody, be careful not to fall into it yourself.","russian":"Не рой другому яму, сам в неё упадёшь.","somali":"Booraan hadimo ha qodin, ku dhici doontaana mooyee"},{"english":"Childhood is a grudge, which will be forgotten in time.","russian":"Детство — это обида, которая со временем забудется.","somali":"Carruurnimo waa ciil laga weynaaday"},{"english":"You cannot pursue profit and maintain dignity.","russian":"Нельзя и к выгоде стремиться, и достоинство сохранять.","somali":"Dan iyo xarrago is weyday"},{"english":"The ground quakes under a rascal [i.e. it seems to him that he is pursued].","russian":"Под пройдохой земля дрожит [т. е. ему кажется, что за ним гонятся].","somali":"Dhagarqabe dhulkaa u dhaqdhaqaaqa"},{"english":"A barking hyena is better than one which keeps silent [it is less dangerous].","russian":"Лающая гиена лучше молчащей [не так опасна].","somali":"Dhurwaa kan ciya iyo kan aammusan, kan ciyaa roon"},{"english":"If you make a mistake in the first letter of a word, it will not become correct by the last letter [lit.: by the last Surah of the Quran].","russian":"Если ошибиться в первой букве слова, то к последней букве [букв.: к последней суре Корана] оно уже не выправится.","somali":"Erayga alifka ku qalloocdaa al bakhra kuma tooso"},{"english":"When the camels graze together each herdsman keeps close to his own.","russian":"Когда верблюды пасутся вместе, каждый пастух держится поближе к своим (верблюдам).","somali":"Geeljire geela waa wada jiraa, waana kala jiraa"},{"english":"Death is better when it takes a man you do not know [i.e. a stranger] or a herdsman you do not see [i.e. one who is far away].","russian":"Лучше, когда умирает человек, которого ты не знаешь [т. е. чужой], или пастух, которого ты не видишь [т. е. находящийся далеко от тебя].","somali":"Geeriyi nin aanad garanayn iyo geeljiray ku roon tahay"},{"english":"A shoe is thrown out together with the shit it has got into.","russian":"Башмак выбрасывают вместе с дерьмом, в которое он вляпался.","somali":"Kab iyo xaarkeed waa laysla tuuraa"},{"english":"When I had strength I did not have brains, now I have brains but do not have strength.","russian":"Когда была сила, ума не было, а теперь есть ум, да нет силы.","somali":"Markii aan tamar hayayna talo ma hayn, maantoon talo hayana tamar ma hayo"},{"english":"A wet man is not afraid of water.","russian":"Мокрый воды не боится","somali":"Nin qoyani biyo iskama dhowro"},{"english":"Truth and teeth should both be polished.","russian":"Правду и зубы следует чистить до блеска.","somali":"Run iyo ilkaba waa la caddeeyaa"},{"english":"Of all men, three types are the worst: he who does not know how to sew (clothes), he who does not know how to get (clothes), and he who does not know how to take care of them.","russian":"Хуже всех мужчин трое: тот, кто не умеет шить одежду, тот, кто не умеет её добыть, и тот, кто не умеет её носить.","somali":"Saddex baa rag ugu liita: ma-toshe, ma-tashade iyo ma-tashiishe"},{"english":"If you fail to do what you want, do what you have to do.","russian":"Если не выходит, как хочешь, — делай, что можешь.","somali":"Sidaad dooneyso haddaad weydo, sidaad ka badin weyso ayaa la yeelaa"},{"english":"Is it possible to gnaw a hego and not break any teeth?","russian":"Можно ли и хего грызть, и зубы не поломать?","somali":"Sidee xeego loo xagtaa, ilkana u nabad galaan?"},{"english":"A caught thief has no excuse.","russian":"Пойманный вор оправдаться не может.","somali":"Tuug la qabtay talo ma leh"},{"english":"Slaughter the heifer so that the bull gets the message [i.e. punish one person as a warning to another].","russian":"Зарежь тёлку, чтобы бык понял [т. е. накажи одного в назидание другому].","somali":"Weysha gowrac, dibigu ha ku quustee"},{"english":"A snake-bite received at the age of six kills you at the age of sixty [i.e. evil lingers a long time].","russian":"Укус змеи, полученный тобою в шесть лет, в шестьдесят лет тебя с ног валит [т. е. зло долго даёт о себе знать].","somali":"Abeesadii lix jir kugu qaniintaa lixdan jir bay kugu dishaa"},{"english":"The world is like a shadow: in the morning it is turned towards one direction, in the evening towards the opposite one [i.e. it is changeable].","russian":"Мир подобен тени: утром (глядит) в одну сторону, а вечером – в другую [т. е.  он изменчив].","somali":"Adduunyo waa hooska labadiisa gelin"},{"english":"Catch hold of a brisket or at least a leg [i.e. it is better to get something than nothing].","russian":"Хватай грудинку или хотя бы ногу [т. е. лучше получить хоть что-нибудь, чем ничего].","somali":"Ama leg hay, ama lug hay"},{"english":"Breaking a custom angers God.","russian":"Нарушение обычая Бога гневит.","somali":"Caado la gooyey caro Allay leedahay"},{"english":"An enemy should be treated to fresh milk [i.e. should be treated as a dear guest in order to lessen his vigilance].","russian":"Врага угощают парным молоком [т. е. принимают, как дорогого гостя, чтобы усыпить его бдительность].","somali":"Cadowgaaga caano mac ayaa la siiyaa"},{"english":"In war, sons die, but none are born.","russian":"На войне сыновья погибают, но не рождаются.","somali":"Dagaal wiil baa ku dhinta ee wiil kuma dhasho"},{"english":"Somebody else's clothes do not warm you.","russian":"Чужая одежда не греет","somali":"Dhar aanad lahayni dhaxan kaama cesho"},{"english":"Cut off the cow's horn while (the knife) is still hot.","russian":"Коровий рог режут, пока (нож) не остыл.","somali":"Gees lo'aad kulaylkaa lagu gooyaa"},{"english":"If you have managed to avoid (premature) death, you will not manage to avoid old age.","russian":"Если от (преждевременной) смерти тебе удалось уйти, то от старости уйти тебе не удастся.","somali":"Hadday geeriyi ku deyn lahayd, gabow baan ku daayeen"},{"english":"If you can defeat someone while sitting, there is no need to stand up.","russian":"Если можешь одолеть кого-то сидя, вставать незачем.","somali":"Nin aad fadhi kaga adag tahay looma sare joogsado"},{"english":"One fears for the man who does not fear for himself [i.e. who does not take care of himself].","russian":"Кто сам за себя не боится [т. е. сам себя не бережёт], за того боязно.","somali":"Nin aan baqin waa loo baqaa"},{"english":"Only God knows what is best.","russian":"Только Бог знает, что лучше.","somali":"Roonaa Rabbaa og"},{"english":"Three types – beggars, ailing people and gluttons – are all disliked equally.","russian":"Троих — попрошаек, больных и обжор — одинаково не любят.","somali":"Saddex waa layku nacaa: baryo badan, bukto badan iyo baahi badan"},{"english":"Women’s tricks are impossible to fathom.","russian":"Женские хитрости постичь до конца невозможно.","somali":"Sir naageed lama sal gaaro"},{"english":"An unconsidered [lit.: unchewed] decision will make you suffer.","russian":"Необдуманное [букв.: непрожёванное] решение заставит тебя страдать.","somali":"Taladaan la ruugin waa lagu rafaadaa"},{"english":"Give your stick (to hold) only to someone you can take it back from.","russian":"Свою палку давай (подержать) лишь тому, у кого сможешь её отнять.","somali":"Ushaada nin aad ka qaadan kartid ayaa loo dhiibtaa"},{"english":"What will ruin you is what you have got accustomed to.","russian":"К чему привык – то тебя и погубит.","somali":"Waxaad barataaba waa baaskaa"},{"english":"Not keeping a promise is the same as renouncing your faith.","russian":"Не сдержать обещания — то же, что отречься от веры.","somali":"Ballandarro waa diindarro"},{"english":"A wicked man is lacking either one eye or one leg [which means that he cannot damage the people round him in full measure].","russian":"Злому человеку недостаёт либо глаза, либо ноги [что и не позволяет ему в полной мере вредить окружающим].","somali":"Belo ama il la'ayd, ama lug la'ayd"},{"english":"Expect from people and the forest what you least expect [i.e. people’s actions are hard to predict].","russian":"От людей и от леса жди того, чего и ждать нельзя [т. е. поступки людей трудно предугадать].","somali":"Dad iyo duurba wax aadan filayn baa kaaga soo baxa"},{"english":"A fool is not a kinsman [i.e. one cannot rely upon him].","russian":"Дурак – не родич [т. е. на него нельзя положиться].","somali":"Doqoni sokeeye ma aha"},{"english":"He who sits close to a cooking pot gets a (good) bone.","russian":"Кто ближе всех к котлу, тому и (лучшая) кость достаётся.","somali":"Dheri ninkii ag jooga ayaa lafta kala baxa"},{"english":"If the hand which used to catch [i.e. steal] is chopped off, the stump will twitch [i.e. it will still try to catch something].","russian":"Отрубили руку, привыкшую хватать [т. е. воровать], — культя дёргается [т. е.  всё ещё пытается что-либо ухватить].","somali":"Gacantii qaad-qaad barata gummudkeedaa   dhaqdhaqaaqa"},{"english":"He who comes late ruins the gathering [because his untimely remarks interfere with a decision already agreed upon].","russian":"Опоздавший всю сходку губит [так как своими суждениями не к месту мешает утвердить уже согласованное решение].","somali":"Gadaal-ka-gaar waa goob-dumis"},{"english":"If two men spent a night far from each other, neither knows how the other is now.","russian":"Если двое провели ночь вдали друг от друга, ни один из них не знает, что сейчас с другим.","somali":"Laba kala bariday kala war la'"},{"english":"The short-eared sheep does not hear the complaints about the drought [i.e. a well-fed person does not think about the suffering of others].","russian":"Короткоухая овца жалоб на засуху не слышит [т. е. сытый не думает о страданиях других].","somali":"Lax dhukani abaar moog"},{"english":"A sheep is slaughtered on the deck on which she herself is standing [i.e. everybody gets according to his deserts].","russian":"Овцу режут на том настиле, на который она сама встаёт.","somali":"Lax walba shillalkay is dhigtaa lagu qalaa"},{"english":"Annoying guests and beggars are equally disliked.","russian":"Назойливых гостей и попрошаек одинаково не любят.","somali":"Marti badan iyo baryo badanba waa laysku nacaa"},{"english":"A woman [ lit.: women] will not get off the man she has brought down.","russian":"Кого женщина [букв.: женщины] повалит – с того не слезет.","somali":"Naago nin ay legdaan kama kacaan"},{"english":"He who does not sweat [i.e. does not toil] does not eat his fill.","russian":"Кто не потеет [т. е. не трудится], тот досыта не ест.","somali":"Nin aan dhididini ma dhergo"},{"english":"He who divides something gets either nothing or too much.","russian":"Тому, кто делит, либо не остаётся ничего, либо достаётся слишком много.","somali":"Qaybshe qad ama qaaday"},{"english":"Men like tea, women like conversation.","russian":"Мужчины любят чай, а женщины — разговоры.","somali":"Rag waa shaah, dumarna waa sheeko"},{"english":"As you are placed when caught by prayer-time, just so pray.","russian":"Где тебя застало время молитвы, там и молись.","somali":"Salaadi siday kuu qabataa loo tukadaa"},{"english":"To count [money, things] is not shameful.","russian":"Считать [деньги, вещи] не стыдно.","somali":"Xisaabi xil ma leh"},{"english":"One cannot be cured of foolishness.","russian":"От глупости не излечишься.","somali":"Doqonnimo daawo ma leh"},{"english":"It is all the same to a stone whether you touch it or squeeze it [i.e. it does not matter].","russian":"Камень хоть сжимай, хоть трогай – ему ничего не сделается [букв.: ему всё равно].","somali":"Dhagax taabasho iyo tuujin waa isugu mid"},{"english":"The mother of a coward does not lose her son.","russian":"Мать труса сына не теряет","somali":"Fuley habartii ma gablanto"},{"english":"The snake’s teeth grow from one jaw [lit.: they are joined below].","russian":"Зубы у змеи растут из одной челюсти [букв.: соединены внизу].","somali":"Ilko abeeso hoos bay ka xidhiidhaan"},{"english":"If people support each other they do not fall.","russian":"Если люди поддерживают друг друга, они не падают.","somali":"Iskaashato ma kufto"},{"english":"For a twenty-year-old, making a mistake is like jumping over a log [i.e. just as easy].","russian":"Двадцатилетнему ошибиться – что через бревно перескочить [т. е. так же легко].","somali":"Labaatanjir intuu geed ka booduu talo ka boodaa"},{"english":"A man vomits not where he wants to but where he feels sick.","russian":"Человек блюёт не там, где хочет, а там, где его стошнит.","somali":"Matag meeshaad doonayso kuguma simo"},{"english":"If you leave where you are loved, you will come to where you are hated.","russian":"Если уйдёшь оттуда, где тебя любят, – придёшь туда, где тебя ненавидят.","somali":"Meel lagaa jecel yahay haddaad ka tagtid, meel lagaa neceb yahay ayaad tagtaa"},{"english":"You sew sandals for him, while he sews a shroud for you.","russian":"Ты ему шьёшь сандалии, а он тебе — саван","somali":"Nin aad kabtiisa toleysid oo kafantaada tolaya"},{"english":"As a man eats, so he works.","russian":"Кто как ест, тот так и работает.","somali":"Ninba intuu cunuu ciidamiyaa"},{"english":"It is not the folly that gets beaten, but its owner.","russian":"Бьют не дурь, а её хозяина.","somali":"Qooq ma jabee ninkiisaa jaba"},{"english":"News you already know is not interesting.","russian":"Новость, которую ты уже знаешь, неинтересна.","somali":"War la qabaa xiiso ma leh"},{"english":"Marry a woman you are sure of and you will have no doubt of your children [i.e. you will be sure that you are their father].","russian":"Женись на женщине, которой доверяешь, и тебе не придётся сомневаться в своих детях [то есть, в том, что они действительно твои].","somali":"Waxaad taqaan guurso, waxaad taqaan ha kuu dhashee"},{"english":"A full stomach does not sympathize with an empty stomach.","russian":"Сытый живот голодному животу не сочувствует.","somali":"Calool dheregsani calool baahan kama naxdo"},{"english":"Honesty does not come empty-handed [i.e. honesty does not go unrewarded].","russian":"Честности с пустыми руками не бывает [т. е. честность не остаётся без вознаграждения].","somali":"Daacadi ma hungowdo"},{"english":"A fool himself carries the rope with which he will be bound [lit.: carries it on his own elbow].","russian":"Дурак сам несёт верёвку, которой его свяжут [букв.: несёт её на собственном локте].","somali":"Doqoni xadhkaha lagu xidhayo xusulladay ku sidataa"},{"english":"One cannot sit at home [i.e. idle] and enjoy almond nut soup.","russian":"Нельзя и дома сидеть [т. е. бездельничать], и миндальным супом лакомиться.","somali":"Fadhi iyo fuud yicibeed laysku waa"},{"english":"Allah does not disgrace a brave man.","russian":"Храброго Бог не обижает.","somali":"Geesi Allah ma xilo"},{"english":"In good times be ready for bad times [i.e. well-being is not eternal and can be replaced by misfortune].","russian":"Живя в добре, жди худа [т. е. благополучие не вечно и может смениться несчастьем].","somali":"Khayr wax kaama dhimee shar u toog hay"},{"english":"He is with you but not with you [i.e. he only pretends to be your friend].","russian":"Он с тобой, но не с тобой [т. е. он лишь притворяется твоим другом].","somali":"Kula-jire, kaa-jire"},{"english":"As a place stands, so stand in it (i.e. what is the place where you are, so behave in it).","russian":"Как место стоит, так в нём и стой (т. е. каково место, где ты находишься, так в нём себя и веди).","somali":"Meel siday u taallo ayaa loola yaallaa"},{"english":"For a man, making a mistake is like jumping over a log [i.e. just as easy].","russian":"Человеку ошибиться – что через бревно перескочить [т. е. так же легко].","somali":"Nin intuu geed ka boodo ayuu talo ka boodaa"},{"english":"He whose tongue is more eloquent than yours, will deprive you of your father's inheritance.","russian":"У кого язык лучше подвешен, тот и отцовское наследство у тебя отспорит.","somali":"Nin kaa hadal badan dhaxalka aabbahaa ayuu kaa qadiyaa"},{"english":"A patient man will get his share.","russian":"Терпеливый без своей доли не останется.","somali":"Nin sabraa sed leh"},{"english":"He fasted for a hundred days but broke his fast with carrion.","russian":"Сто дней постился, а разговелся падалью.","somali":"Ninkii boqolka soomay oo bakhtiga ku affuray"},{"english":"To get rid of the smoke, one throws out the charred log [i.e. together with the bad, one throws out the good].","russian":"Избавляясь от дыма, выбрасывают и головню [т. е. вместе с плохим выбрасывают и хорошее].","somali":"Qori iyo qiiqiisa waa laysla tuuraa"},{"english":"It is you who need advice, it does not need you [i.e. advice should not be neglected].","russian":"Совет нужен тебе, а не ты ему [т.е. советом пренебрегать не следует].","somali":"Talo adigaa ku nool ee iyadu kuguma noola"},{"english":"The right decision does not come by itself [i.e. it has to be found].","russian":"Верное решение само не приходит [т. е. его надо искать].","somali":"Talo isuma kaa sheegto"},{"english":"The hare sits under one bush but looks out for another [to which it might run if endangered].","russian":"Пока заяц сидит под одним кустом, он себе уже другой присматривает [чтобы было куда бежать в случае опасности].","somali":"Bakayle intuu bur ku jiruu bur kale daydaydaa"},{"english":"One does not weep like that over a goat [i.e. the real reason for the grief is something else, more serious].","russian":"По козе так не плачут [т. е. настоящая причина горя в чём-то другом, более серьёзном].","somali":"Baroorta ceesaanta ka weyn"},{"english":"If misfortune does not come to you, it comes to one of your peers [i.e. someone always has misfortune: if not you, then someone else].","russian":"Не у тебя беда, так у сверстника [т. е. беда всегда у кого-нибудь есть: не у тебя, так у другого].","somali":"Belaayo intay kaa maqan tahay, qayrkaa bay ku maqan tahay"},{"english":"When milk spills, one catches it by the tail [i.e. when everything is already lost, one tries to save at least the little that can still be saved].","russian":"Когда молоко проливается, его и за хвост ловят [т. е. когда всё уже теряется, стараются спасти хотя бы то немногое, что ещё можно спасти].","somali":"Caano daatay dabadoodaa la qabtaa"},{"english":"How you curse a fool in the afternoon so will he curse you in the evening.","russian":"Как ты дурака обзовёшь днём, так он тебя обзовёт вечером.","somali":"Doqon wixii casarkii lagu caayo ayay cishihii kugu caaysaa"},{"english":"The fool knew where they fought but not where they were reconciled.","russian":"Дурак знал, где дрались, да не знал, где помирились.","somali":"Doqoni meeshii lagu dagaalay waa ogeyd ee meel lagu heshiiyey ma ogeyn"},{"english":"If you pull in one direction and I pull in another, the hands of both of us will get tired.","russian":"Если ты будешь тянуть в одну сторону, а я – в другую, у обоих руки устанут.","somali":"‘I jiid’, ‘aan ku jiidee’ waa gacmo-daalis"},{"english":"It is better to have an aching leg than an aching spirit [lit.: stomach]; i.e. it is better to endure hardship now than to regret later what one has left undone.","russian":"Пусть лучше болит нога, чем душа [букв.: живот]; т. е. лучше перенести тяготы сейчас, чем потом сожалеть о несделанном.","somali":"Intay calooshu buki lahayd cagtu ha bukto"},{"english":"(An offence) is forgotten not by the offended but by the offender.","russian":"(Обиду) забывает не обиженный, а обидчик.","somali":"La-yeele ma hilmaamo, laakiin yeele wuu hilmaamaa"},{"english":"He who has not travelled the world has no eyes.","russian":"Кто земли не обошёл, у того глаз нет.","somali":"Nin aan dhul marini dhaayo la’"},{"english":"As the branches in a fence are piled up, so should they be taken down.","russian":"Как ветви в изгороди сложены, так их и разбирать следует.","somali":"Oodo dhacameed siday u kala sarreeyaan baa loo kala guraa"},{"english":"One should take (green) branches to the grave, but should not take them away.","russian":"(Зелёные) ветки на могилу приносить можно, а уносить нельзя.","somali":"Qabri qori-saarid mooyee qori-ka-qaadid ma leh"},{"english":"The neck of a miniature antelope cannot be divided in half [i.e. it is too small].","russian":"Шею карликовой антилопы пополам не разделишь [т. е. она слишком мала].","somali":"Sagaaro laba tun oo la kala qalo ma leh"},{"english":"I had milked for you much milk but you have left me only a little.","russian":"Я надоил тебе много (молока), а ты мне оставил мало.","somali":"Sidaan kuugu lisay iiguma hambayn"},{"english":"You will never get rid of what you were born with [lit: it will not roam from you].","russian":"С чем родился, от того не избавишься [букв.: от того не откочуешь].","somali":"Sinji waa magguuraan"},{"english":"The new moon [lit.: a moon that is three days old] will lead you out of your own home but will not lead you into someone else’s [i.e. a decision made prematurely will come to no good].","russian":"Молодой месяц [букв.: месяц, которому три дня] выведет тебя из собственного дома, но в чужой не приведёт [т. е. решение, принятое преждевременно, до добра не доведёт].","somali":"Bilsaddex gurigaagana way kaa kexeysaa, guri kalana kuma gaarsiiso"},{"english":"When a grown-up stumbles and falls, children laugh.","russian":"Когда взрослый спотыкается и падает, дети смеются.","somali":"Carruuri haddii aad kuftid way kugu qososhaa"},{"english":"When labour pains begin, one has to forget about shame.","russian":"Когда начинаются родовые схватки, о стыде приходится забыть.","somali":"Hadday fooli timaaddo, gudo-qarsiimo hadhay"},{"english":"If you sit on a dik-dik skin you can only get up from it, not shift about [it is too small].","russian":"Со шкуры карликовой антилопы можно только слезть – подвинуться на ней нельзя [она слишком мала].","somali":"Harag sagaaro ‘iiga kac’ mooye ‘iiga durug’ ma leh"},{"english":"A slip of the tongue does not count [lit.: does not enter speech]; i.e. what was said inadvertently should not be taken into account.","russian":"Оговорка не в счёт [букв.: в речь не входит]; т. е. случайно сказанное не следует принимать в расчёт.","somali":"Helmaan hadal kuma jiro"},{"english":"Above the head there is nothing to stroke.","russian":"Выше головы не погладишь.","somali":"Madax ka kor meel la salaaxo ma leh"},{"english":"Ah, what will he now suckle and with what?","russian":"Ах, чем и что он (теперь) сосать будет?","somali":"Maxay ku nuugtaa, maxayse ka nuugtaa?"},{"english":"He who is unjust will not succeed [i.e. injustice does not lead to well-being].","russian":"Несправедливому удачи не будет [т. е. несправедливость не приводит к благополучию].","somali":"Nin gardaran ma guuleysto"},{"english":"For a simple man even a sab holds water.","russian":"У бесхитростного человека даже саб воду держит.","somali":"Sir-ma-qabe saab baa biyo u celiya"},{"english":"A small path will take you to a big road.","russian":"Малая тропка выводит на большую дорогу.","somali":"Wadiiqada yari waddada weyn bay kugu riddaa"},{"english":"News hurries to a meeting place [i.e. what is secret sooner or later becomes known].","russian":"Весть спешит туда, где собираются люди [т. е. тайное рано или поздно становится явным].","somali":"War jiraaba cakaaruu iman"},{"english":"What is straight to one man is crooked to another [i.e. what one man likes, another dislikes].","russian":"Что одному ровно, то другому горбато [т. е. что нравится одному, то не нравится другому].","somali":"Wax qof la toosan baa qof kale la tuur leh"},{"english":"If there is no wife, then there is no soul.","russian":"Без жены – всё равно что без души.","somali":"Naagla'aani waa nafla'aan"},{"english":"Woman is a disaster one cannot do without","russian":"Женщина — несчастье, без которого не обойтись.","somali":"Naag waa belaayo loo baahan yahay"},{"english":"No one is more afraid than a thief.","russian":"Пугливее вора никого нет.","somali":"Tuug wax ka tuhun badan"},{"english":"Days [lit.: mornings] are more than lines in the Quran [i.e. by memorizing one line a day, you can learn the entire Quran by heart].","russian":"Дней [букв.: утр] больше, чем строк в Коране [т. е., уча в день по строке в день, можно выучить весь Коран].","somali":"Subax iyo sadar, subax baa badan"}];